export {ToggleGroup, ToggleGroupItem} from './toggle-group';
import type {ComponentPropsWithoutRef} from 'react';
import type {ToggleGroup, ToggleGroupItem} from './toggle-group';
/** Props of `ToggleGroup`. */
export type ToggleGroupProps = ComponentPropsWithoutRef<typeof ToggleGroup>;
/** Props of `ToggleGroupItem`. */
export type ToggleGroupItemProps = ComponentPropsWithoutRef<typeof ToggleGroupItem>;

import {forwardRef, type ComponentPropsWithoutRef, type ElementRef} from 'react';
import {ToggleGroup as RadixToggleGroup} from 'radix-ui';
import {cx} from '../../utils/cx';

/** Props of ToggleGroup: `type`, `value`, `defaultValue`, `onValueChange`, `disabled`. */
export type ToggleGroupProps = ComponentPropsWithoutRef<typeof RadixToggleGroup.Root>;

/** `type="single"` for one choice (like a segmented control) or `type="multiple"`. Arrow keys move between items. */
export const ToggleGroup = forwardRef<
  ElementRef<typeof RadixToggleGroup.Root>,
  ComponentPropsWithoutRef<typeof RadixToggleGroup.Root>
>(function ToggleGroup({className, ...rest}, ref) {
  return <RadixToggleGroup.Root ref={ref} className={cx('toggle-group', className)} {...rest} />;
});
/** One toggle button in a `ToggleGroup`; give it a `value` and an accessible name. */
export const ToggleGroupItem = forwardRef<
  ElementRef<typeof RadixToggleGroup.Item>,
  ComponentPropsWithoutRef<typeof RadixToggleGroup.Item>
>(function ToggleGroupItem({className, ...rest}, ref) {
  return <RadixToggleGroup.Item ref={ref} className={cx('toggle', className)} {...rest} />;
});
